-- 0144: Jujutsu Kaisen — „Wie heißt Yujis Technik, die er später entdeckt?“ markierte
-- „Blitzschlag“ als richtig (Index 2); gemeint ist die Seelenberührung (Index 1), wie die
-- Erklärung sagt. Dazu Ablenker „Zerlegung“ ersetzt — Yuji nutzt im späten Manga auch
-- Dismantle, das wäre eine zweite richtige Antwort. Idempotent.
update question_translations set options = jsonb_set(options, '{3}', to_jsonb('Ten Shadows'::text)) where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wie heißt Yujis Technik, die er später entdeckt?');
